        case (.pauldrons, .towering): heroDetailPauldronsTowering(ctx, ink)
        case (.warPlate, .lithe): heroDetailWarPlateLithe(ctx, ink)
        case (.warPlate, .standard): heroDetailWarPlateStandard(ctx, ink)
        case (.warPlate, .broad): heroDetailWarPlateBroad(ctx, ink)
        case (.warPlate, .stout): heroDetailWarPlateStout(ctx, ink)
        case (.warPlate, .towering): heroDetailWarPlateTowering(ctx, ink)
        }
    }

    static func drawHeroWings(_ style: WingStyle, _ build: BodyBuild, _ ctx: CGContext, _ ink: HeroInk) {
        switch (style, build) {
        case (.plain, _): break
        case (.angel, .lithe): heroWingsAngelLithe(ctx, ink)
        case (.angel, .standard): heroWingsAngelStandard(ctx, ink)
        case (.angel, .broad): heroWingsAngelBroad(ctx, ink)
        case (.angel, .stout): heroWingsAngelStout(ctx, ink)
        case (.angel, .towering): heroWingsAngelTowering(ctx, ink)
        case (.demon, .lithe): heroWingsDemonLithe(ctx, ink)
        case (.demon, .standard): heroWingsDemonStandard(ctx, ink)
        case (.demon, .broad): heroWingsDemonBroad(ctx, ink)
        case (.demon, .stout): heroWingsDemonStout(ctx, ink)
        case (.demon, .towering): heroWingsDemonTowering(ctx, ink)
        }
    }
}
